"""T159 (ledger T148, runbook R6): writes one attempt record per card of 2026-11-11/12 into data/diag/attempts/g3/B*.txt, every figure read from its result file (file#key), and the MM3 scan request .mm3/requests/t159_attempts_g3.yaml with the same 22 questions as MM3-0676. No article text in any record.
    python3 t159_attempt_records.py (from projects/world-state)"""
import json, pathlib
P = "runs/pulse/"; J = lambda f: json.load(open(P + f)); D = pathlib.Path("/workspace/data/diag/attempts/g3"); D.mkdir(exist_ok=True)
def g(d, k):
    for p in k.split("."): d = d[int(p)] if p.isdigit() else d[p]
    return d
t148, t148s, t149, t150, t152, t153, t154, t155, t156, t157, t158 = (J(x) for x in ("t148/t148_checkthat_function.json", "t148/summary.json", "t149/t149_domain_wording.json", "t150/t150_topic_head.json", "t152/t152_factuality_maven.json", "t153/t153_a03_paired.json", "t154/t154_aggregator.json", "t155/t155_pooled.json", "t156/t156_lines.json", "t157/t157_function_combiner.json", "t158/t158_place_floor.json"))
R = []
def rec(i, tried, claim, ev, comp, test, cav, notshow, nxt): R.append((f"B{i:02d}", f"ATTEMPT B{i:02d}\nWHAT WAS TRIED: {tried}\nTHE CLAIM: {claim}\nEVIDENCE (figures with files and keys): {ev}\nHOW IT WAS COMPARED: {comp}\nPRE-WRITTEN PASS OR FAIL TEST AND PREDICTION: {test}\nCAVEATS AND CORRECTIONS: {cav}\nWHAT IT DID NOT SHOW: {notshow}\nNEXT STEP STATED: {nxt}\n"))
rec(1, "Runbook R1: hosted Jev function_opinion on 2,076 CheckThat English subjectivity sentences (scoring only, human labels).", "Jev's opinion answer ranks subjective above objective sentences well enough to pass the 0.80 AUROC bar, but not at the fixed 0.5 line.",
    f"AUROC {g(t148,'function_opinion.auc')} (95% {g(t148,'function_opinion.ci95')}) (runs/pulse/t148/t148_checkthat_function.json#function_opinion); balanced accuracy at 0.5 {g(t148s,'balanced_accuracy_at_0_5')} (runs/pulse/t148/summary.json#balanced_accuracy_at_0_5); n {g(t148,'n')}.",
    "Human CheckThat labels, none used for training; compared with the bar 0.80 and with 1 minus function_report (AUROC 0.758).", "Written before the run: pass if AUROC >= 0.80; predicted p 0.55 that it passes. It passed; the 0.5 line did not.", "Bootstrap of sentences; CheckThat 'subjective' is wider than our 'opinion'.", "Whether any line or combination reaches balanced accuracy 0.80 (see B08).", "Pick the line on dev_en and score once on test_en_labeled (done, B08).")
rec(2, "Runbook R2: three wordings of the 17-option Domain choice on MN-DS fresh2 gold, 300 stories to pick, a disjoint 500 held out.", "No wording beats the current one; wording is not the Domain lever.",
    f"Pick accuracy {g(t149,'pick_acc')} (runs/pulse/t149/t149_domain_wording.json#pick_acc); held-out current {g(t149,'held_acc.A')} against winner {g(t149,'held_acc.B')}, paired difference {g(t149,'held_diff')} (95% {g(t149,'held_diff_ci95')}) (#held_diff_ci95); n {g(t149,'n_held')}.",
    "Human MN-DS labels (outside), same stories for all wordings, paired bootstrap on the held-out set.", "Written before the run: pass if the winner beats the current wording by 0.03 or more with an interval above 0; predicted p 0.35. It failed.", "MN-DS gold may be noisy; the unexplained token count of variant C was half of A's, so the cost figure may be understated.", "Why Domain is 0.56 to 0.60 against 0.80 (label noise, taxonomy, or head).", "Check gold noise and confusion pairs, then the learning curve.")
t = g(t150, "variants.T_sonnet_all_plus_jev_topic"); c = g(t150, "variants.C_sonnet_all_retrained"); v2 = g(t150, "variants.v2_deployed")
rec(3, "Runbook R3: topic head trained on Sonnet labels plus 2,560 Jev topic rows (T135 stories and MN-DS excluded), saved as sparse_heads_v3.pkl.", "The Jev rows do not lower MN-DS topic accuracy but do not cut the abstain share either, so v3 is not deployed.",
    f"MN-DS topic two-guess {g(t,'mnds_topic_two_guess.rate')} against {g(c,'mnds_topic_two_guess.rate')} for Sonnet-only retrained, n {g(t,'mnds_topic_two_guess.n')} (runs/pulse/t150/t150_topic_head.json#variants); abstain on the 100 T135 stories {g(t,'abstain_t135.either')} against {g(c,'abstain_t135.either')} retrained and {g(v2,'abstain_t135.either')} for the deployed v2.",
    "Human MN-DS labels through the topic-to-IPTC map (indirect, coarse); abstain measured on the same 100 stories before and after.", "Written before the run: deploy rule 'not lower than Sonnet-only by more than 0.01' (predicted p 0.7, met); 'abstain falls below 43' (predicted p 0.35, not met).", "Two-guess accuracy through a coarse map; the 100 stories are few.", "Whether more Jev rows (a bulk read) move the abstain share.", "Put the bulk-read case to the owner with this result.")
rec(4, "Hosted Jev on 1,818 MAVEN-FACT marked events (human labels, 909 certain-to-have-happened) with the happened question and the production factuality choice; then a decision line chosen on one half of the documents and scored on the other.", "At the 0.5 line Factuality is below the 0.80 bar; with a fitted line 0.85 it reaches the bar's edge.",
    f"happened balanced accuracy {g(t152,'happened_at_0_5.balanced_accuracy')} (95% {g(t152,'happened_at_0_5.ci95')}) (runs/pulse/t152/t152_factuality_maven.json#happened_at_0_5), AUROC {g(t152,'happened_auc')}; production choice {g(t152,'choice_asserted_is_yes.balanced_accuracy')}; line {g(t156,'factuality.line')} chosen on one half gives {g(t156,'factuality.bal_acc_at_line_on_score_half')} (95% {g(t156,'factuality.ci95')}) on the other (runs/pulse/t156/t156_lines.json#factuality).",
    "Human MAVEN-FACT labels (outside); the line was chosen on documents the scoring half does not contain.", "Written before the run: pass if balanced accuracy >= 0.80 (predicted p 0.5 for happened, p 0.35 for the production choice; both failed at 0.5); the line card predicted p 0.35 for >= 0.80 and reached 0.798.", "A 40-item pilot gave 0.804 and was optimistic; events in one document share a half; the class map from CT/PS/Uu to yes or no is mine.", "A fresh human-labelled split, which does not exist locally.", "Decide whether production uses the happened question; find a fresh judge.")
p = g(t153, "paired_embedding_minus_counts")
rec(5, "Rerun of T119 with saved per-story predictions: word and character counts with and without a bge-small embedding, 5 grouped folds over 1,736 engine stories (attempt A03).", "Adding the embedding does not change the heads' agreement with the engine readings.",
    f"Presence AUROC difference {g(p,'presence_auroc_diff')} (95% {g(p,'presence_ci95')}), direction AUROC {g(p,'direction_auroc_diff')} (95% {g(p,'direction_auroc_ci95')}), direction accuracy {g(p,'direction_acc_diff')} (runs/pulse/t153/t153_a03_paired.json#paired_embedding_minus_counts); the rerun reproduces T119 exactly.",
    "Clef's stored engine reading (a model reference, agreement not accuracy); paired bootstrap over stories.", "Written before the run: the paired interval includes 0 (predicted p 0.8); it did.", "Bootstrap resamples stories, not feeds; one encoder only; the reference is a model.", "Another encoder or a different reference.", "None; closes attempt A03.")
a = g(t154, "clef_stored"); b = g(t154, "engine_read")
rec(6, "Learned logistic aggregator of the 39 Jev dial answers on 1,000 engine stories, 5 folds (attempt A13), result now saved.", "A learned aggregator beats the any-dial-at-0.7 rule on agreement with the reference readings.",
    f"Against Clef stored: AUROC {g(a,'auroc')}, agreement {g(a,'agreement_at_0_5')}, difference over the rule {g(a,'agreement_diff_vs_rule')} (95% {g(a,'agreement_diff_ci95')}); against the engine read: AUROC {g(b,'auroc')}, difference {g(b,'agreement_diff_vs_rule')} (95% {g(b,'agreement_diff_ci95')}) (runs/pulse/t154/t154_aggregator.json).",
    "Clef's stored reading and the engine's own read (model references, no outside truth for condition presence); paired bootstrap over stories.", "Written before the run: reproduces AUROC 0.8183 within 0.01 (predicted p 0.8); it matched exactly.", "Agreement, not accuracy; condition presence has no outside judge, so the head stays not admissible.", "Whether presence is right in any outside sense.", "Find a judge for conditions (SENTiVENT covers economy events only).")
rec(7, "Fine-tuned bge-small against the sparse word-count heads, 5 grouped folds over 2,488 engine stories (attempt A08), epoch chosen on each fold's own dev split.", "Fine-tuning does not beat the sparse heads at this label count.",
    f"Fine-tuned minus sparse: presence AUROC {g(t155,'fine_minus_sparse.presence_auroc')} (95% {g(t155,'fine_minus_sparse.presence_ci95')}), direction AUROC {g(t155,'fine_minus_sparse.direction_auroc')} (95% {g(t155,'fine_minus_sparse.direction_auroc_ci95')}), direction accuracy {g(t155,'fine_minus_sparse.direction_accuracy')} (runs/pulse/t155/t155_pooled.json#fine_minus_sparse); majority guess {g(t155,'direction_majority')}.",
    "Engine stored readings (model reference); same folds and stories for both models; paired bootstrap pooled over folds.", "Written before the run: presence gain not above +0.02 (predicted p 0.8, held); direction interval excludes 0 (predicted p 0.45, not met).", "The earlier single-fold hint of a direction gain did not hold; bootstrap over stories not feeds; reference is a model.", "Other label counts or encoders.", "None; closes attempt A08.")
rec(8, "Function: line chosen on CheckThat dev_en (462) and scored once on test_en_labeled (300); then a logistic combiner of the five function answers, same split.", "Neither a better line nor a combiner lifts Function to the 0.80 bar.",
    f"Line {g(t156,'function.line')}: balanced accuracy {g(t156,'function.bal_acc_at_line_on_score_set')} (95% {g(t156,'function.ci95')}) (runs/pulse/t156/t156_lines.json#function); combiner {g(t157,'bal_acc')} (95% {g(t157,'ci95')}), AUROC {g(t157,'auroc')} against the single question's {g(t157,'single_opinion_auroc')} (runs/pulse/t157/t157_function_combiner.json).",
    "Human CheckThat labels (outside), fit and score splits disjoint, scored once.", "Written before the run: line card predicted p 0.25 for >= 0.80 and the combiner p 0.3; both failed.", "The test set has 300 sentences so intervals are wide; the label concept (subjective) is broader than our definition.", "Whether a subjectivity-worded question would pass.", "Optional: one subjectivity-worded read of the 1,818 CheckThat sentences.")
rec(9, "Place sanity floor: Jev place_region against the feed's own region tag on 556 regionally tagged engine stories.", "Place is not broken, but there is no judge for it.",
    f"Share in the allowed set {g(t158,'share')} (95% {g(t158,'ci95')}), n {g(t158,'n')} (runs/pulse/t158/t158_place_floor.json); feeds tagged Asia {g(t158,'per_feed_region.Asia.share')}.",
    "The feed's region tag, which says where the source is, not where the story is (a proxy, stated in the file).", "Written before the run: share >= 0.70 (predicted p 0.55); met by a hair. My region map is fixed in the task text.", "A proxy, not truth; 444 of 1,000 stories have no tag; my Asia mapping may be at fault.", "True place accuracy.", "Derive place from place-name spans in the story text or find a geo-tagged news set.")
for k, s in R: (D / (k + ".txt")).write_text(s)
Q = [("evidence", "correctness", "yes", ["Does `{file}` give a measured figure together with a file or ledger id it came from?", "Does `{file}` state what the main figure was compared against?", "Does the figure in `{file}` support the conclusion that `{file}` states?"]),
     ("validity", "correctness", "yes", ["Does `{file}` score on data the method did not train on?", "Does `{file}` use a reference other than another model's labels for its key claim?", "Does `{file}` give an interval or a paired comparison for its main difference?"]),
     ("overreach", "design-risk", "no", ["Does `{file}` claim more than its figures show?", "Could the result in `{file}` come from training data leaking into the scoring data?", "Is the sample in `{file}` too small to support its conclusion?"]),
     ("done", None, "yes", ["Does `{file}` record a pass or fail test written before the run?", "Does `{file}` name what it did not show?", "Does `{file}` state a concrete next step?"]),
     ("repeat", None, "yes", ["Could the run in `{file}` be repeated from the files it names?", "Is the result in `{file}` independent of the other attempts' results?", "Does `{file}` keep its corrections of earlier claims visible?"]),
     ("use", None, "yes", ["Does the result in `{file}` change what should be done next?", "Is the conclusion in `{file}` stated with its scope?", "Would a reviewer be able to disprove the conclusion in `{file}` from what it shows?"])]
y = ["mak:", "  goal: Each attempt record's conclusion is supported by its own evidence and is safe to build on", "  depth: standard", "  over:", "    file: data/diag/attempts/g3/B*.txt", "  ask:", "    file:", "      concerns:"]; n = 0
for name, fam, ps, qs in Q:
    y += [f"        {name}:"] + ([f"          family: {fam}"] if fam else []) + [f"          pass: {ps}"]
    for q in qs: n += 1; y.append(f"          {n}: {json.dumps(q)}")
y += ["      decisions:", "        verdict:", "          pass: [supported]", "          19:", "            choice: Is the conclusion in `{file}` supported by its own evidence?", "            options: [supported, partly-supported, not-supported, unverifiable]",
      "        weakest:", "          pass: [none, low]", "          20:", "            scale: How serious is the weakest point of the conclusion in `{file}`?", "            levels: [none, low, medium, high]",
      "        action:", "          pass: [build-on]", "          21:", "            choice: What should be done with the conclusion in `{file}`?", "            options: [build-on, retest, drop, extend]",
      "        scope:", "          pass: [enough]", "          22:", "            choice: Can this be answered from the file shown?", "            options: [enough, partial, missing]",
      "mdl:", "  why: validate", "  area: data", "  stage: review", "  change: config", "  risk: medium", "  problem: Validate which of the nine attempts of 2026-11-11 and 12 are supported by their own evidence, and which need a retest"]
pathlib.Path("/workspace/.mm3/requests/t159_attempts_g3.yaml").write_text("\n".join(y) + "\n"); print(len(R), "records;", n + 4, "questions")
